import sys

def solve():
    # Base string f_0
    base = "What are you doing at the end of the world? Are you busy? Will you save us?"
    len_base = len(base)

    # Precompute lengths for f_n
    # Since k <= 10^18, we only need lengths up to this value.
    # The length grows exponentially, so it will exceed 10^18 very quickly (around n=60).
    MAX_K = 10**18
    INF = MAX_K + 7

    lengths = [0] * (MAX_K.bit_length() + 100) # Sufficient size
    lengths[0] = len_base

    for i in range(1, len(lengths)):
        # f_i = "What are you doing while sending " + f_{i-1} + "? Are you busy? Will you send " + f_{i-1} + "?"
        # Prefix: "What are you doing while sending " (34 chars)
        # Suffix: "? Are you busy? Will you send " (32 chars)
        # Suffix2: "?" (1 char)
        # Total fixed parts: 34 + 32 + 1 = 67
        # Variable parts: 2 * len(f_{i-1})

        prev_len = lengths[i-1]
        if prev_len >= INF:
            lengths[i] = INF
        else:
            new_len = 67 + 2 * prev_len
            if new_len >= INF:
                lengths[i] = INF
            else:
                lengths[i] = new_len

    # If n is large enough, the length is effectively infinite for our purposes (>= 10^18)
    # We can find the smallest n such that lengths[n] >= 10^18
    threshold_n = 0
    for i in range(len(lengths)):
        if lengths[i] >= MAX_K:
            threshold_n = i
            break

    # Function to get k-th character of f_n
    def get_char(n, k):
        if k > lengths[n]:
            return '.'

        # If n is 0, return character from base string
        if n == 0:
            return base[k-1]

        # If n is large enough, the structure is:
        # Prefix (34) + f_{n-1} (variable) + Middle (32) + f_{n-1} (variable) + Suffix (1)
        # However, for very large n, f_{n-1} is huge.
        # We can simulate the descent.

        # Constants for the structure of f_i (i >= 1)
        prefix = "What are you doing while sending "
        middle = "? Are you busy? Will you send "
        suffix = "?"

        # Lengths of fixed parts
        len_prefix = 34
        len_middle = 32
        len_suffix = 1

        # We need to find which part k falls into
        # k is 1-based

        # Check prefix
        if k <= len_prefix:
            return prefix[k-1]

        k -= len_prefix

        # Check first f_{n-1}
        # Note: if n is very large, lengths[n-1] is effectively infinite (>= MAX_K)
        # But we have precomputed lengths. If n-1 >= threshold_n, then lengths[n-1] >= MAX_K.
        # Since k <= MAX_K, if lengths[n-1] >= MAX_K, then k is definitely within the first f_{n-1}.

        if n - 1 >= threshold_n:
            # The first f_{n-1} is huge enough to contain k
            return get_char(n-1, k)
        else:
            len_first = lengths[n-1]
            if k <= len_first:
                return get_char(n-1, k)
            else:
                k -= len_first

                # Check middle
                if k <= len_middle:
                    return middle[k-1]
                else:
                    k -= len_middle

                    # Check second f_{n-1}
                    if n - 1 >= threshold_n:
                        return get_char(n-1, k)
                    else:
                        len_second = lengths[n-1]
                        if k <= len_second:
                            return get_char(n-1, k)
                        else:
                            k -= len_second

                            # Check suffix
                            if k <= len_suffix:
                                return suffix[k-1]
                            else:
                                # Should not happen if k <= lengths[n]
                                return '.'

    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        q = int(next(iterator))
    except StopIteration:
        return

    results = []
    for _ in range(q):
        n = int(next(iterator))
        k = int(next(iterator))

        # If n is larger than our precomputed array, treat it as having infinite length
        # and the structure is the same as threshold_n.
        if n >= len(lengths):
            n = len(lengths) - 1

        # If n is still beyond threshold_n, we can just use threshold_n logic
        # because lengths[n] == lengths[threshold_n] == INF
        if n > threshold_n:
            n = threshold_n

        results.append(get_char(n, k))

    print("".join(results))

if __name__ == "__main__":
    solve()
